const M=new Map(M0.map(r=>[r[0],r.slice(1)]));
const fill=(s,p)=>p?String(s).replace(/\{(\w+)\}/g,(m,k)=>p[k]!=null?String(p[k]):m):String(s);
// το κείμενο στη γλώσσα l· χωρίς μετάφραση μένει ελληνικό
function tx(l,s,p){let t=s;if(l&&l!=='el'){const r=M.get(s),i=L8.indexOf(l);if(r&&i>=0&&r[i])t=r[i]}return fill(t,p)}
const has=s=>M.has(s);
// ημερομηνίες: «Δευ 19/10» και «19 Οκτ» σε κάθε γλώσσα
const pd0=s=>{const[y,m,d]=String(s).split('-').map(Number);return new Date(y,m-1,d)};
const fmtD=(l,s)=>{if(!s)return '—';const d=pd0(s);return (DAYS[l]||DAYS.en)[d.getDay()]+' '+d.getDate()+'/'+(d.getMonth()+1)};
const fmtM=(l,s)=>{if(!s)return '—';const d=pd0(s);return d.getDate()+' '+(MONS[l]||MONS.en)[d.getMonth()]};
// απόσταση: μέτρα ως 1 χλμ., μετά χιλιόμετρα με ένα δεκαδικό
const COMMA=['el','sq','tr','kmr'];
const dist=(l,m)=>m<1000?tx(l,'{n} μ.',{n:Math.round(m/10)*10}):tx(l,'{n} χλμ.',{n:String(Math.round(m/100)/10).replace('.',COMMA.includes(l)?',':'.')});
// μεταγραφή ελληνικών με λατινικά (κατά ΕΛΟΤ 743, απλοποιημένη), για ονόματα έργων, διευθύνσεις και εργασίες
const GR=/[Ͱ-Ͽἀ-῿]/;
const hasGreek=s=>GR.test(String(s||''));
const TL={α:'a',β:'v',γ:'g',δ:'d',ε:'e',ζ:'z',η:'i',θ:'th',ι:'i',ϊ:'i',κ:'k',λ:'l',μ:'m',ν:'n',ξ:'x',ο:'o',π:'p',ρ:'r',σ:'s',ς:'s',τ:'t',υ:'y',ϋ:'y',φ:'f',χ:'ch',ψ:'ps',ω:'o'};
const VLESS='θκξπσςτφχψ';
function tlit(s){
  // χωρίς τόνους, με τα διαλυτικά (ϊ, ϋ) για να μη γίνονται δίφθογγοι
  const n=String(s||'').normalize('NFD').replace(/[̀́͂̓̔ͅ]/g,'').normalize('NFC');
  let out='';
  for(let i=0;i<n.length;i++){
    const c=n[i],lc=c.toLowerCase(),nx=(n[i+1]||'').toLowerCase(),nx2=(n[i+2]||'').toLowerCase();
    let r=null,k=0;
    if(lc==='ο'&&nx==='υ'){r='ou';k=1}
    else if((lc==='α'||lc==='ε')&&nx==='υ'){r=(lc==='α'?'a':'e')+(!nx2||!TL[nx2]||VLESS.includes(nx2)?'f':'v');k=1}
    else if(lc==='γ'&&'γξχ'.includes(nx)&&nx)r='n';
    else r=TL[lc];
    if(r==null){out+=c;continue}
    if(c!==lc){const nu=n[i+1+k]||'',all=nu&&nu!==nu.toLowerCase();r=all?r.toUpperCase():r[0].toUpperCase()+r.slice(1)}
    out+=r;i+=k}
  return out}
root.ErgoI18n={LANGS,L8,RTL,okLang,isRTL,langName,DAYS,MONS,M0,tx,fill,has,fmtD,fmtM,dist,hasGreek,tlit};
